insert into public.game_items (id, statement, original_wording, d, r, pollster, fielded, url, notes, topic) values
  ('congress-term-limits', 'Members of Congress should face term limits.', 'Favor/oppose: limiting the number of terms that members of Congress can serve', 86, 90, 'Pew Research Center', '2023', 'https://www.pewresearch.org/politics/2023/09/19/how-americans-view-proposals-to-change-the-political-system/', 'Dems and Dem-leaning independents vs. Reps and Rep-leaning independents. ATP Waves 129/130; report released Sep 2023; exact field dates not shown on page.', 'Government & elections'),
  ('scotus-age-limit', 'Supreme Court justices should have a maximum age limit.', 'Favor/oppose: a maximum age limit for Supreme Court justices', 82, 68, 'Pew Research Center', '2023', 'https://www.pewresearch.org/politics/2023/09/19/how-americans-view-proposals-to-change-the-political-system/', 'Dems and Dem-leaning independents vs. Reps and Rep-leaning independents. Released Sep 2023.', 'Government & elections'),
  ('popular-vote', 'The presidential candidate who gets the most votes nationwide should win.', 'Change the system so the candidate who receives the most votes nationwide wins the presidency vs. keep current Electoral College system', 82, 47, 'Pew Research Center', '2023', 'https://www.pewresearch.org/politics/2023/09/19/how-americans-view-proposals-to-change-the-political-system/', 'Dems and Dem-leaning independents vs. Reps and Rep-leaning independents. Released Sep 2023. A 2024 Pew reading (D 80, R 46) is cited in Pew''s Jul 2026 short read.', 'Government & elections'),
  ('voter-id', 'Voters should have to show government-issued ID.', 'Favor/oppose: requiring voters to show government-issued identification', 61, 93, 'Pew Research Center', '2023', 'https://www.pewresearch.org/politics/2023/09/19/how-americans-view-proposals-to-change-the-political-system/', 'Dems and Dem-leaning independents vs. Reps and Rep-leaning independents. Released Sep 2023.', 'Government & elections'),
  ('auto-voter-registration', 'All eligible citizens should be automatically registered to vote.', 'Favor/oppose: automatically registering all eligible citizens to vote', 80, 45, 'Pew Research Center', '2023', 'https://www.pewresearch.org/politics/2023/09/19/how-americans-view-proposals-to-change-the-political-system/', 'Dems and Dem-leaning independents vs. Reps and Rep-leaning independents. Released Sep 2023.', 'Government & elections'),
  ('stock-trading-ban', 'Members of Congress should not be allowed to trade individual stocks.', 'Should elected officials [members of Congress] be allowed to trade individual stocks? (% should not be allowed)', 80, 77, 'Economist/YouGov', 'May 2026', 'https://yougov.com/en-us/articles/54851-most-americans-think-congressional-corruption-is-widespread-may-22-26-2026-economist-yougov-poll', 'Democrats vs Republicans as reported by YouGov (party ID). Fielded May 22-26, 2026. Article also ran an experimental ''banned'' wording (D 69%; R not reported).', 'Government & elections'),
  ('obey-supreme-court', 'The president must follow Supreme Court rulings, even ones he disagrees with.', 'If the Supreme Court rules against the president in a case, does the president have the power to ignore that ruling, or is the president required to do as the ruling says? (% required)', 92, 80, 'Marquette Law School', 'Sep 2025', 'https://law.marquette.edu/poll/2025/10/02/new-marquette-law-school-poll-national-survey-finds-continuing-large-majority-who-say-a-president-must-obey-the-supreme-court/', 'Democrats vs Republicans; page does not state whether leaners included. Fielded Sep 15-24, 2025.', 'Government & elections'),
  ('guns-mental-illness', 'People with mental illnesses should be prevented from buying guns.', 'Favor/oppose: preventing people with mental illnesses from purchasing guns', 89, 88, 'Pew Research Center', '2023', 'https://www.pewresearch.org/short-reads/2024/07/24/key-facts-about-americans-and-guns/', 'Labeled ''Democrats''/''Republicans'' on page (Pew normally includes leaners). Page is Jul 2024 compilation; policy items appear to come from the Jun 2023 survey but field dates for these items are not explicitly stated.', 'Guns'),
  ('gun-age-21', 'The minimum age for buying guns should be 21.', 'Favor/oppose: increasing the minimum age for buying guns to 21 years old', 90, 69, 'Pew Research Center', '2023', 'https://www.pewresearch.org/short-reads/2024/07/24/key-facts-about-americans-and-guns/', 'Same caveat as guns-mental-illness re: field dates.', 'Guns'),
  ('teachers-carry-guns', 'Teachers and school officials should be allowed to carry guns in K-12 schools.', 'Favor/oppose: allowing teachers and school officials to carry guns in K-12 schools', 27, 74, 'Pew Research Center', '2023', 'https://www.pewresearch.org/short-reads/2024/07/24/key-facts-about-americans-and-guns/', 'Same caveat as guns-mental-illness re: field dates.', 'Guns'),
  ('concealed-carry-more-places', 'People should be allowed to carry concealed guns in more places.', 'Favor/oppose: allowing people to carry concealed guns in more places', 19, 71, 'Pew Research Center', '2023', 'https://www.pewresearch.org/short-reads/2024/07/24/key-facts-about-americans-and-guns/', 'Same caveat as guns-mental-illness re: field dates.', 'Guns'),
  ('more-solar', 'The U.S. should expand solar power.', 'Favor/oppose more solar power (Pew paraphrase; verbatim in linked questionnaire)', 91, 61, 'Pew Research Center', 'Apr-May 2025', 'https://www.pewresearch.org/science/2025/06/05/americans-views-on-energy-at-the-start-of-trumps-second-term/', 'Dems and Dem-leaning independents vs. Reps and Rep-leaning independents. Fielded Apr 28-May 4, 2025.', 'Energy & climate'),
  ('more-wind', 'The U.S. should expand wind power.', 'Favor/oppose more wind power (Pew paraphrase; verbatim in linked questionnaire)', 87, 48, 'Pew Research Center', 'Apr-May 2025', 'https://www.pewresearch.org/science/2025/06/05/americans-views-on-energy-at-the-start-of-trumps-second-term/', 'Dems and Dem-leaning independents vs. Reps and Rep-leaning independents. Fielded Apr 28-May 4, 2025.', 'Energy & climate'),
  ('more-nuclear', 'The U.S. should build more nuclear power plants.', 'Favor/oppose more nuclear power plants to generate electricity', 52, 69, 'Pew Research Center', 'Apr-May 2025', 'https://www.pewresearch.org/short-reads/2025/10/16/support-for-expanding-nuclear-power-is-up-in-both-parties-since-2020/', 'Dems and Dem-leaning independents vs. Reps and Rep-leaning independents. Fielded Apr 28-May 4, 2025.', 'Energy & climate'),
  ('climate-gov-too-little', 'The federal government is doing too little to reduce the effects of climate change.', 'Is the federal government doing too much, too little, or about the right amount to reduce the effects of climate change? (% too little)', 87, 31, 'Pew Research Center', 'Mar 2026', 'https://www.pewresearch.org/science/2026/05/28/americans-are-increasingly-pessimistic-about-avoiding-the-worst-effects-of-climate-change/', 'Dems and Dem-leaning independents vs. Reps and Rep-leaning independents. Fielded Mar 16-22, 2026. ''Agree'' = said ''too little''.', 'Energy & climate'),
  ('phone-ban-class', 'Middle and high school students should be banned from using cellphones during class.', 'Would you support or oppose a ban that prevents middle and high school students from using cellphones during class?', 74, 81, 'Pew Research Center', 'May-Jun 2026', 'https://www.pewresearch.org/short-reads/2026/07/29/more-americans-now-support-than-oppose-all-day-school-cellphone-bans/', 'Dems and Dem-leaning independents vs. Reps and Rep-leaning independents. Fielded May 26-Jun 1, 2026.', 'Tech & kids'),
  ('phone-ban-all-day', 'Middle and high school students should be banned from using cellphones for the entire school day.', 'Would you support or oppose a ban that prevents middle and high school students from using cellphones during the entire school day?', 44, 55, 'Pew Research Center', 'May-Jun 2026', 'https://www.pewresearch.org/short-reads/2026/07/29/more-americans-now-support-than-oppose-all-day-school-cellphone-bans/', 'Dems and Dem-leaning independents vs. Reps and Rep-leaning independents. Fielded May 26-Jun 1, 2026.', 'Tech & kids'),
  ('social-media-under-16-ban', 'Anyone under 16 should be banned from using social media.', 'Would you support or oppose a ban that prevents anyone under the age of 16 from using social media sites?', 54, 59, 'Pew Research Center', 'May-Jun 2026', 'https://www.pewresearch.org/short-reads/2026/07/01/majority-of-americans-support-banning-social-media-for-kids-under-16/', 'Dems and Dem-leaning independents vs. Reps and Rep-leaning independents. Fielded May 26-Jun 1, 2026.', 'Tech & kids'),
  ('social-media-parental-consent', 'Social media companies should require parental consent for minors to open an account.', 'Would you support social media companies requiring parental consent for minors to create a social media account?', 83, 89, 'Pew Research Center', 'May-Jun 2026', 'https://www.pewresearch.org/short-reads/2026/07/01/majority-of-americans-support-banning-social-media-for-kids-under-16/', 'Dems and Dem-leaning independents vs. Reps and Rep-leaning independents. Fielded May 26-Jun 1, 2026.', 'Tech & kids'),
  ('social-media-age-verification', 'Social media sites should require people to verify their age.', 'Would you support social media companies requiring people to verify their age before using social media sites?', 76, 81, 'Pew Research Center', 'May-Jun 2026', 'https://www.pewresearch.org/short-reads/2026/07/01/majority-of-americans-support-banning-social-media-for-kids-under-16/', 'Dems and Dem-leaning independents vs. Reps and Rep-leaning independents. Fielded May 26-Jun 1, 2026.', 'Tech & kids'),
  ('social-media-time-limits', 'Social media companies should limit how much time minors spend on their sites.', 'Would you support social media companies setting limits on how much time minors can spend on social media?', 78, 79, 'Pew Research Center', 'May-Jun 2026', 'https://www.pewresearch.org/short-reads/2026/07/01/majority-of-americans-support-banning-social-media-for-kids-under-16/', 'Dems and Dem-leaning independents vs. Reps and Rep-leaning independents. Fielded May 26-Jun 1, 2026.', 'Tech & kids'),
  ('gov-restrict-false-info', 'The government should restrict false information online, even if it limits freedom of information.', 'The U.S. government should take steps to restrict false information online, even if it limits freedom of information', 58, 43, 'Pew Research Center', 'Feb-Mar 2025', 'https://www.pewresearch.org/short-reads/2025/04/14/support-dips-for-us-government-tech-companies-restricting-false-or-violent-online-content/', 'Dems and Dem-leaning independents vs. Reps and Rep-leaning independents. Fielded Feb 24-Mar 2, 2025.', 'Tech & kids'),
  ('tech-restrict-false-info', 'Tech companies should restrict false information online, even if it limits freedom of information.', 'Tech companies should take steps to restrict false information online, even if it limits freedom of information', 73, 47, 'Pew Research Center', 'Feb-Mar 2025', 'https://www.pewresearch.org/short-reads/2025/04/14/support-dips-for-us-government-tech-companies-restricting-false-or-violent-online-content/', 'Dems and Dem-leaning independents vs. Reps and Rep-leaning independents. Fielded Feb 24-Mar 2, 2025.', 'Tech & kids'),
  ('ai-more-concerned', 'I''m more concerned than excited about the growing use of AI in daily life.', 'Does the increased use of artificial intelligence in daily life make you feel more excited than concerned, more concerned than excited, or equally both? (% more concerned)', 51, 50, 'Pew Research Center', 'Jun 2025', 'https://www.pewresearch.org/short-reads/2025/11/06/republicans-democrats-now-equally-concerned-about-ai-in-daily-life-but-views-on-regulation-differ/', 'Dems and Dem-leaning independents vs. Reps and Rep-leaning independents. Fielded Jun 9-15, 2025.', 'Tech & kids'),
  ('trust-us-regulate-ai', 'I trust the U.S. government to regulate AI effectively.', 'How much do you trust the U.S. to regulate the use of AI effectively? (% a lot or some)', 36, 54, 'Pew Research Center', 'Mar 2025', 'https://www.pewresearch.org/short-reads/2025/11/06/republicans-democrats-now-equally-concerned-about-ai-in-daily-life-but-views-on-regulation-differ/', 'Dems and Dem-leaning independents vs. Reps and Rep-leaning independents. Fielded Mar 24-30, 2025.', 'Tech & kids'),
  ('extend-aca-credits', 'Congress should extend the enhanced ACA health insurance tax credits.', 'Should Congress extend the enhanced premium tax credits for ACA marketplace enrollees, or let them expire? (% extend)', 91, 63, 'KFF', 'Jun 2025', 'https://www.kff.org/affordable-care-act/poll-most-of-the-public-support-extending-the-acas-enhanced-premium-tax-credits-including-most-republicans-and-maga-supporters/', 'Democrats vs Republicans (party ID; leaners not specified). Fielded Jun 4-8, 2025. Exact wording paraphrased by KFF. R support fell to 50% in KFF''s Oct-Nov 2025 poll (no D figure given there).', 'Health & economy'),
  ('gov-health-coverage', 'The federal government is responsible for making sure all Americans have health coverage.', 'Is it the federal government''s responsibility to make sure all Americans have health care coverage?', 90, 41, 'Pew Research Center', 'Nov 2025', 'https://www.pewresearch.org/short-reads/2025/12/10/most-americans-say-government-has-a-responsibility-to-ensure-health-care-coverage/', 'Dems and Dem-leaning independents vs. Reps and Rep-leaning independents. Fielded Nov 17-30, 2025.', 'Health & economy'),
  ('drug-price-regulation', 'There should be more government regulation of prescription drug prices.', 'Is there more, less, or about the right amount of government regulation of prescription drug prices? (% not as much as there should be)', 77, 68, 'KFF', 'Feb-Mar 2026', 'https://www.kff.org/public-opinion/poll-public-worries-about-prescription-drug-costs-reach-new-high-most-across-political-parties-want-government-to-do-more-to-regulate-prices/', 'Democrats vs Republicans; leaners not specified. Fielded Feb 24-Mar 2, 2026. Exact wording not shown on page.', 'Health & economy'),
  ('social-security-no-cuts', 'Social Security benefits should not be reduced in any way.', 'Social Security benefits should not be reduced in any way (vs. reductions need to be considered)', 83, 77, 'Pew Research Center', '2024', 'https://www.pewresearch.org/politics/2024/06/24/americans-views-of-government-aid-to-poor-role-in-health-care-and-social-security/', 'Labeled Democrats/Republicans on page. Report published Jun 2024; field dates not stated on page.', 'Health & economy'),
  ('raise-corporate-taxes', 'Tax rates on large businesses and corporations should be raised.', 'Should tax rates on large businesses and corporations be raised, lowered, or kept the same? (% raised)', 81, 43, 'Pew Research Center', 'Jan-Feb 2025', 'https://www.pewresearch.org/short-reads/2025/03/19/most-americans-continue-to-favor-raising-taxes-on-corporations-higher-income-households/', 'Dems and Dem-leaning independents vs. Reps and Rep-leaning independents. Fielded Jan 27-Feb 2, 2025.', 'Health & economy'),
  ('raise-taxes-400k', 'Tax rates on household income over $400,000 should be raised.', 'Should tax rates on household income over $400,000 be raised, lowered, or kept the same? (% raised)', 74, 43, 'Pew Research Center', 'Jan-Feb 2025', 'https://www.pewresearch.org/short-reads/2025/03/19/most-americans-continue-to-favor-raising-taxes-on-corporations-higher-income-households/', 'Dems and Dem-leaning independents vs. Reps and Rep-leaning independents. Fielded Jan 27-Feb 2, 2025.', 'Health & economy'),
  ('gov-retirement-income', 'The federal government is responsible for providing adequate retirement income for all.', 'Does the federal government have a responsibility to provide adequate income in retirement for all Americans?', 81, 50, 'Pew Research Center', 'Apr 2025', 'https://www.pewresearch.org/short-reads/2025/05/06/americans-see-a-role-for-the-federal-government-in-many-domains-but-some-large-partisan-divisions-persist/', 'Dems and Dem-leaning independents vs. Reps and Rep-leaning independents. Fielded Apr 7-13, 2025.', 'Health & economy'),
  ('gov-internet-access', 'The federal government is responsible for providing high-speed internet to all.', 'Does the federal government have a responsibility to provide high-speed internet access for all Americans?', 60, 31, 'Pew Research Center', 'Apr 2025', 'https://www.pewresearch.org/short-reads/2025/05/06/americans-see-a-role-for-the-federal-government-in-many-domains-but-some-large-partisan-divisions-persist/', 'Dems and Dem-leaning independents vs. Reps and Rep-leaning independents. Fielded Apr 7-13, 2025.', 'Health & economy'),
  ('nato-commitment', 'The U.S. should maintain or increase its commitment to NATO.', 'Should the U.S. increase, maintain, decrease, or withdraw its commitment to NATO? (% increase or maintain)', 86, 55, 'Chicago Council on Global Affairs', 'Jun 2026', 'https://globalaffairs.org/research/public-opinion-survey/strong-bipartisan-support-nato-ahead-2026-summit', 'Democrats vs Republicans (Council-Ipsos). Fielded Jun 5-8, 2026.', 'World'),
  ('russia-sanctions', 'The U.S. should impose additional economic and diplomatic sanctions on Russia.', 'Support/oppose: additional economic and diplomatic sanctions on Russia', 75, 69, 'Chicago Council on Global Affairs', 'Feb 2026', 'https://globalaffairs.org/research/public-opinion-survey/americans-oppose-ceding-donbas-russia-amid-push-peace-deal', 'Democrats vs Republicans (Council-Ipsos). Fielded Feb 6-8, 2026. Verbatim wording not shown on page.', 'World'),
  ('ukraine-military-aid', 'The U.S. should provide military aid to Ukraine.', 'Support/oppose: providing military aid to Ukraine', 72, 43, 'Chicago Council on Global Affairs', 'Feb 2026', 'https://globalaffairs.org/research/public-opinion-survey/americans-oppose-ceding-donbas-russia-amid-push-peace-deal', 'Democrats vs Republicans (Council-Ipsos). Fielded Feb 6-8, 2026. Verbatim wording not shown on page.', 'World'),
  ('immigration-good-thing', 'Immigration is a good thing for this country today.', 'Is immigration a good thing or a bad thing for this country today? (Gallup paraphrase on page)', 91, 50, 'Gallup', 'Jun 2026', 'https://news.gallup.com/poll/712289/americans-support-immigration-down-strong.aspx', 'Democrats vs Republicans; page does not state whether leaners included. Fielded Jun 1-15, 2026.', 'Immigration'),
  ('deport-illegal-immigrants', 'Immigrants living in the U.S. illegally should be deported to their home countries.', 'Do you favor or oppose deporting immigrants who are living in the United States illegally back to their home countries?', 29, 93, 'Marquette Law School', 'Jan-Feb 2025', 'https://law.marquette.edu/poll/2025/02/12/new-marquette-law-school-poll-national-survey-finds-public-strongly-favors-some-trump-policies-strongly-opposes-others/', 'Democrats vs Republicans; leaners not specified. Fielded Jan 27-Feb 5, 2025.', 'Immigration'),
  ('deport-long-term-workers', 'Illegal immigrants who''ve lived here for years, have jobs and no criminal record should be deported.', 'Favor/oppose deporting immigrants living in the U.S. illegally back to their home countries if they have lived here for many years, have a job and no criminal record', 22, 67, 'Marquette Law School', 'Jan-Feb 2025', 'https://law.marquette.edu/poll/2025/02/12/new-marquette-law-school-poll-national-survey-finds-public-strongly-favors-some-trump-policies-strongly-opposes-others/', 'Democrats vs Republicans; leaners not specified. Fielded Jan 27-Feb 5, 2025. Full wording truncated on fetched page; conditions paraphrased from article.', 'Immigration'),
  ('school-vouchers', 'Tax-funded vouchers should help pay for children''s private school tuition.', 'Favor/oppose: tax-funded vouchers that help pay for a child''s tuition at a private school', 26, 47, 'AP-NORC', 'Jun 2025', 'https://apnorc.org/projects/the-public-holds-nuanced-views-on-the-role-of-religion-in-public-schools/', 'Democrats vs Republicans; leaners not specified. Fielded Jun 5-9, 2025.', 'Schools & rights'),
  ('school-book-lists', 'Public schools should be required to give parents lists of the books students read.', 'Favor/oppose: requiring public schools to provide parents with lists of books', 40, 67, 'AP-NORC', 'Jun 2025', 'https://apnorc.org/projects/the-public-holds-nuanced-views-on-the-role-of-religion-in-public-schools/', 'Democrats vs Republicans. Fielded Jun 5-9, 2025. Full wording not shown on page.', 'Schools & rights'),
  ('free-speech-important', 'Freedom of speech is extremely or very important to American democracy.', 'How important is freedom of speech? (% extremely/very important)', 87, 86, 'AP-NORC', 'Jun 2025', 'https://apnorc.org/projects/the-public-holds-nuanced-views-on-the-role-of-religion-in-public-schools/', 'Democrats vs Republicans. Fielded Jun 5-9, 2025. Exact question stem not shown on page.', 'Schools & rights'),
  ('free-press-important', 'Freedom of the press is extremely or very important.', 'How important is freedom of the press? (% extremely/very important)', 80, 64, 'AP-NORC', 'Jun 2025', 'https://apnorc.org/projects/the-public-holds-nuanced-views-on-the-role-of-religion-in-public-schools/', 'Democrats vs Republicans. Fielded Jun 5-9, 2025. Exact question stem not shown on page.', 'Schools & rights')
